insert into custody_saved select 'revoke',pg_temp.write(pg_temp.request(65,'revoke',(v->>'eventId')::uuid),1),pg_temp.request(65,'revoke',(v->>'eventId')::uuid) from custody_saved where kind='activate';
set constraints all immediate;set constraints all deferred;
do $$begin begin perform pg_temp.admission();raise exception 'revoked policy granted new authority';exception when insufficient_privilege then null;end;end$$;
select pg_temp.ok(pg_temp.accepted_admission()->>'policyState'='revoked','accepted task retains actual revoked state without forged revoked:false');
update public.tenants set is_demo=true where id=pg_temp.id(11);
insert into custody_saved select 'demo-activate',pg_temp.write(pg_temp.demo_request(93,'activate',(v->>'eventId')::uuid),3),pg_temp.demo_request(93,'activate',(v->>'eventId')::uuid) from custody_saved where kind='demo-approve';
set constraints all immediate;set constraints all deferred;
select pg_temp.ok(pg_temp.admission(24)->>'kind'='new_authority','explicit approved live demo profile authorizes');
select pg_temp.ok((select activation_epoch=2 from public.local_custody_policy_heads where policy_id=pg_temp.id(24)),'local activation epochs monotonic across policy versions, never cloud revision coercion');
update public.tenants set is_demo=false where id=pg_temp.id(11);
do $$begin begin perform pg_temp.admission(24);raise exception 'non-demo silently admitted under demo policy';exception when insufficient_privilege then null;end;end$$;
select pg_temp.ok(pg_temp.write((select request_text from custody_saved where kind='demo-request'),2)->'replayed'='true'::jsonb,'historical demo request remains positive after eligibility changes');
insert into custody_saved select 'demo-revoke',pg_temp.write(pg_temp.demo_request(94,'revoke',(v->>'eventId')::uuid),2),pg_temp.demo_request(94,'revoke',(v->>'eventId')::uuid) from custody_saved where kind='demo-activate';
set constraints all immediate;set constraints all deferred;
-- Receipt replay remains historical proof and cannot reactivate a revoked head.
select pg_temp.ok(pg_temp.write((select request_text from custody_saved where kind='activate'),3)->'replayed'='true'::jsonb,'historical activation receipt recoverable after revocation');
select pg_temp.ok((select state='revoked' from public.local_custody_policy_heads where policy_id=pg_temp.id(21)),'historical replay never reactivates');
set constraints all immediate;set constraints all deferred;
-- Refused cascade must preserve event/head/ledger row counts and exact retained values.
create function pg_temp.custody_immutable_fingerprint() returns jsonb language sql as $$select jsonb_build_object('events',(select jsonb_build_object('rows',count(*),'sha256',encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(t) order by to_jsonb(t)::text collate "C"),'[]'::jsonb)::text,'UTF8')),'hex')) from public.local_custody_policy_events t),'heads',(select jsonb_build_object('rows',count(*),'sha256',encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(t) order by to_jsonb(t)::text collate "C"),'[]'::jsonb)::text,'UTF8')),'hex')) from public.local_custody_policy_heads t),'ledger',(select jsonb_build_object('rows',count(*),'sha256',encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(t) order by to_jsonb(t)::text collate "C"),'[]'::jsonb)::text,'UTF8')),'hex')) from public.audit_ledger t))$$;
do $$declare denied boolean;before_truncate jsonb;begin
 denied:=false;begin update public.local_custody_policy_events set request_text='{}';exception when insufficient_privilege then denied:=true;end;perform pg_temp.ok(denied,'event UPDATE refused');
 denied:=false;begin delete from public.local_custody_policy_versions;exception when insufficient_privilege then denied:=true;end;perform pg_temp.ok(denied,'policy DELETE refused');
 before_truncate:=pg_temp.custody_immutable_fingerprint();
 denied:=false;begin truncate public.local_custody_policy_events cascade;exception when insufficient_privilege then denied:=true;end;perform pg_temp.ok(denied,'event TRUNCATE CASCADE refused by append-only guard');
 perform pg_temp.ok(before_truncate is not distinct from pg_temp.custody_immutable_fingerprint(),'refused TRUNCATE CASCADE preserves event/head/ledger counts and hashes');
 denied:=false;begin perform public.append_ledger(pg_temp.id(11),gen_random_uuid(),'human',pg_temp.id(1)::text,null,null,null,'custody.local_policy_requested',pg_temp.id(99)::text,repeat('a',64),repeat('b',64),null,null,null,null,'success','{}');set constraints all immediate;exception when check_violation then denied:=true;end;perform pg_temp.ok(denied,'naked generic human receipt refused');
end$$;
select pg_temp.ok(not exists(select 1 from public.verify_ledger(pg_temp.id(11))),'all custody receipts chain verify');
rollback;
